int cf = connect_to_listener(lf);
const char *m = "echo pipe-ok";
CHECK_EQ((int)send(cf, m, strlen(m), 0), (int)strlen(m));
char b[64] = {0};
size_t got = 0;
while (got < strlen(m)) {
ssize_t r = recv(cf, b + got, sizeof b - got - 1, 0);
if (r <= 0) break;
got += (size_t)r;
}
shutdown(cf, SHUT_WR);
pthread_join(t, NULL);
CHECK(got == strlen(m));
CHECK(strstr(b, "pipe-ok") != NULL);
close(cf);
close(lf);

